"use strict";(globalThis.webpackChunkmythogen_engine_blog=globalThis.webpackChunkmythogen_engine_blog||[]).push([[3190],{31418(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>a,default:()=>c,frontMatter:()=>o,metadata:()=>r,toc:()=>d});var i=n(74848),s=n(28453);const o={title:"Lawful Unfairness and Unlawful Deception \u2014 The Dividing Line Between Two Kinds of 'Fraud' in the Lofter Group Case",date:new Date("2026-05-29T00:00:00.000Z"),lang:"en",section:"sober-record",topic:"t-financial",article_tags:{zh:["\u5229\u76ca\u885d\u7a81","\u8cc7\u8a0a\u4e0d\u5c0d\u7a31","\u5408\u7d04\u6cd5","\u6295\u8cc7\u8005\u4fdd\u8b77"],en:["conflict-of-interest","information-asymmetry","contract-law","investor-protection"]},keywords:["Lofter Group","PE fund","Personal Guarantee","fraud","right to information","asset-light","angel investment","startup financing","venture capital"],summary:"Using standard startup financing as a control group, this article dissects the dividing line between PE contracts' lawful suppression and Lofter's information asymmetry toward investors, along with what everyone in business must know about PG risk.",status:"draft",reading_time:12,sidebar_label:"Lawful Unfairness and Unlawful Deception",sidebar_position:20260529,description:"Using standard startup financing as a control group, this article dissects the dividing line between PE contracts' lawful suppression and Lofter's information asymmetry toward investors, along with what everyone in business must know about PG risk."},a='Lawful Unfairness and Unlawful Deception \u2014 The Dividing Line Between Two Kinds of "Fraud" in the Lofter Group Case',r={id:"Diary/\u5408\u6cd5\u7684\u4e0d\u516c\u5e73\u8207\u4e0d\u5408\u6cd5\u7684\u6b3a\u779e\u2014\u2014\u6a02\u98a8\u96c6\u5718\u6848\u4e2d\u5169\u7a2e\u300c\u6b3a\u8a50\u300d\u7684\u5206\u754c\u7dda",title:"Lawful Unfairness and Unlawful Deception \u2014 The Dividing Line Between Two Kinds of 'Fraud' in the Lofter Group Case",description:"Using standard startup financing as a control group, this article dissects the dividing line between PE contracts' lawful suppression and Lofter's information asymmetry toward investors, along with what everyone in business must know about PG risk.",source:"@site/i18n/en/docusaurus-plugin-content-docs/current/Diary/03-\u5408\u6cd5\u7684\u4e0d\u516c\u5e73\u8207\u4e0d\u5408\u6cd5\u7684\u6b3a\u779e\u2014\u2014\u6a02\u98a8\u96c6\u5718\u6848\u4e2d\u5169\u7a2e\u300c\u6b3a\u8a50\u300d\u7684\u5206\u754c\u7dda.md",sourceDirName:"Diary",slug:"/Diary/\u5408\u6cd5\u7684\u4e0d\u516c\u5e73\u8207\u4e0d\u5408\u6cd5\u7684\u6b3a\u779e\u2014\u2014\u6a02\u98a8\u96c6\u5718\u6848\u4e2d\u5169\u7a2e\u300c\u6b3a\u8a50\u300d\u7684\u5206\u754c\u7dda",permalink:"/en/docs/Diary/\u5408\u6cd5\u7684\u4e0d\u516c\u5e73\u8207\u4e0d\u5408\u6cd5\u7684\u6b3a\u779e\u2014\u2014\u6a02\u98a8\u96c6\u5718\u6848\u4e2d\u5169\u7a2e\u300c\u6b3a\u8a50\u300d\u7684\u5206\u754c\u7dda",draft:!1,unlisted:!1,tags:[],version:"current",sidebarPosition:20260529,frontMatter:{title:"Lawful Unfairness and Unlawful Deception \u2014 The Dividing Line Between Two Kinds of 'Fraud' in the Lofter Group Case",date:"2026-05-29T00:00:00.000Z",lang:"en",section:"sober-record",topic:"t-financial",article_tags:{zh:["\u5229\u76ca\u885d\u7a81","\u8cc7\u8a0a\u4e0d\u5c0d\u7a31","\u5408\u7d04\u6cd5","\u6295\u8cc7\u8005\u4fdd\u8b77"],en:["conflict-of-interest","information-asymmetry","contract-law","investor-protection"]},keywords:["Lofter Group","PE fund","Personal Guarantee","fraud","right to information","asset-light","angel investment","startup financing","venture capital"],summary:"Using standard startup financing as a control group, this article dissects the dividing line between PE contracts' lawful suppression and Lofter's information asymmetry toward investors, along with what everyone in business must know about PG risk.",status:"draft",reading_time:12,sidebar_label:"Lawful Unfairness and Unlawful Deception",sidebar_position:20260529,description:"Using standard startup financing as a control group, this article dissects the dividing line between PE contracts' lawful suppression and Lofter's information asymmetry toward investors, along with what everyone in business must know about PG risk."},sidebar:"docs",previous:{title:"Fee Structure Determines Freedom of Speech",permalink:"/en/docs/Diary/\u6536\u8cbb\u7d50\u69cb\u6c7a\u5b9a\u8a00\u8ad6\u81ea\u7531"},next:{title:"China's Industrialisation System",permalink:"/en/docs/Diary/\u4e2d\u570b\u7684\u300c\u9ad8\u901f\u5de5\u696d\u5316\u7cfb\u7d71\u300d\u8207\u5168\u7403\u7af6\u722d\u7684\u771f\u6b63\u554f\u984c"}},l={},d=[{value:"I. Why Do People Feel This Is Fraud?",id:"i-why-do-people-feel-this-is-fraud",level:2},{value:"II. The First Type: PE&#39;s &quot;Lawful Fraud&quot;",id:"ii-the-first-type-pes-lawful-fraud",level:2},{value:"III. The Control Group: How Standard Startup Financing Works",id:"iii-the-control-group-how-standard-startup-financing-works",level:2},{value:"IV. The Second Type: Lofter&#39;s Information Asymmetry Toward Investors",id:"iv-the-second-type-lofters-information-asymmetry-toward-investors",level:2},{value:"V. Why the Two Are Easily Confused",id:"v-why-the-two-are-easily-confused",level:2},{value:"VI. The Grey Zone of Mentor Referrals",id:"vi-the-grey-zone-of-mentor-referrals",level:2},{value:"VII. What Everyone in Business Must Know",id:"vii-what-everyone-in-business-must-know",level:2},{value:"VIII. Conclusion: Same Affair, Two Lines",id:"viii-conclusion-same-affair-two-lines",level:2}];function h(e){const t={blockquote:"blockquote",h1:"h1",h2:"h2",header:"header",p:"p",strong:"strong",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.p,{children:"Author: Nebula Walker\nDate: 29MAY2026\nMYTHOGEN ENGINE (mythogenengine.com)"}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.strong,{children:"\ud83d\udccc Using standard startup financing as a control group, this article dissects the dividing line between PE contracts' lawful suppression and Lofter's information asymmetry toward investors, along with what everyone in business must know about PG risk."})}),"\n",(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"lawful-unfairness-and-unlawful-deception--the-dividing-line-between-two-kinds-of-fraud-in-the-lofter-group-case",children:'Lawful Unfairness and Unlawful Deception \u2014 The Dividing Line Between Two Kinds of "Fraud" in the Lofter Group Case'})}),"\n",(0,i.jsxs)(t.blockquote,{children:["\n",(0,i.jsx)(t.p,{children:'This is the third article in the Lofter Group case analysis series. For background and the food-chain structural analysis, see the first article: "Layer Eats Layer \u2014 The Food Chain Structure of the Lofter Group Case."'}),"\n"]}),"\n",(0,i.jsx)(t.h2,{id:"i-why-do-people-feel-this-is-fraud",children:"I. Why Do People Feel This Is Fraud?"}),"\n",(0,i.jsx)(t.p,{children:'After the Lofter Group incident, "fraud" was the most common label applied by the public. But if you took that word to a lawyer, they would likely shake their head \u2014 the PE financing contract was legal, the PG was voluntarily signed, the properties were real, and the project genuinely had a chance of making money. From a legal standpoint, this was not fraud.'}),"\n",(0,i.jsx)(t.p,{children:'But the victims\' intuition is not groundless either. They felt they were "deceived," and this feeling stems from a real problem: within this affair, two entirely different types of "fraud" coexist, blended together, making them hard to distinguish.'}),"\n",(0,i.jsx)(t.p,{children:"The first type is lawful suppression within a legal framework. The second type is information asymmetry that may involve regulatory violations."}),"\n",(0,i.jsx)(t.p,{children:"They look very similar, but their nature, legality, and the possibility of legal recourse are entirely different."}),"\n",(0,i.jsx)(t.h2,{id:"ii-the-first-type-pes-lawful-fraud",children:'II. The First Type: PE\'s "Lawful Fraud"'}),"\n",(0,i.jsx)(t.p,{children:"PE funds' operations against borrowers \u2014 contract weaponisation, PG binding, Joint and Several Liability \u2014 belong to the first type."}),"\n",(0,i.jsx)(t.p,{children:"Are these operations immoral? Depends on your standards. Are they unfair? Without question. But are they legal? Under the current legal framework, yes."}),"\n",(0,i.jsx)(t.p,{children:"Every clause in PE's contracts has been refined repeatedly by top-tier legal teams to ensure they hold up in any jurisdiction. PG was signed with mutual consent. Interest rates were stated in the contract. Trigger conditions were stated in the contract. Default consequences were stated in the contract. You can argue that the borrower \"didn't understand\" the full implications of these clauses, but legally, once you signed, you are deemed to have agreed."}),"\n",(0,i.jsx)(t.p,{children:'This is what is known as "lawful unfairness." PE crushes you under its weight, but it does so within the framework of contractual freedom. The law protects the validity of contracts, not the equality of bargaining positions. You can condemn PE\'s practices on moral grounds, but it is very difficult to pursue them legally.'}),"\n",(0,i.jsx)(t.p,{children:"If a traditional loan shark charges interest exceeding the statutory ceiling, you can report them to the police. But PE's rates, however high, are legal as long as they are written in the contract and do not exceed statutory limits. The tool has changed from violence to contracts, but the logic is the same."}),"\n",(0,i.jsx)(t.p,{children:"In fact, if you look at it from PE's perspective, requiring PG is an entirely reasonable risk-control measure."}),"\n",(0,i.jsx)(t.p,{children:"Lofter Group's \"asset-light\" model meant: the borrower's project company itself had virtually no assets. The group's equity contribution might be only 3% or even zero; before properties were completed and sold, there was nothing of value on the company's balance sheet to pledge. And Lofter's 8 projects had a total investment approaching HK$10 billion \u2014 meaning the scale of PE's capital deployment was enormous."}),"\n",(0,i.jsx)(t.p,{children:'Ask any financial institution to lend billions to a company with near-zero net assets without requiring additional guarantees, and that would be unreasonable. Any bank, any financial company, faced with this kind of balance sheet, would demand similar protections. PE requiring PG was not a "dirty trick" \u2014 it was a normal response to a high-risk borrower.'}),"\n",(0,i.jsx)(t.p,{children:'So the core question was never "why did PE require PG." The question was: who bears this PG?'}),"\n",(0,i.jsx)(t.p,{children:"In traditional PE financing, PG signatories are the enterprise's actual controllers \u2014 decision-makers, major shareholders, those in charge. They have control over the company's operations, and bearing PG is in some sense commensurate with their power. But in Lofter's model, those who bore PG were not Janice Chow herself (she did not even appear on some project companies' shareholder and director lists), but the retail investors who held shares on a \"one share, one vote\" basis and had virtually no control over the projects' actual operations."}),"\n",(0,i.jsx)(t.p,{children:'PE wanted guarantees; it may not have cared who provided them. Lofter chose to fill that position with retail investors. This is the critical inflection point where the whole affair slides from "lawful unfairness" toward the second type of "fraud."'}),"\n",(0,i.jsx)(t.h2,{id:"iii-the-control-group-how-standard-startup-financing-works",children:"III. The Control Group: How Standard Startup Financing Works"}),"\n",(0,i.jsx)(t.p,{children:"To understand how distorted the Lofter/PE model was, the best approach is to see how standard startup financing operates."}),"\n",(0,i.jsx)(t.p,{children:"In the tech startup world, angel rounds, Series A, and Series B financing see investors contributing money in exchange for equity in the company \u2014 not an IOU. This is a fundamental distinction."}),"\n",(0,i.jsx)(t.p,{children:"Win, and everyone wins together \u2014 investors' shares multiply by tens of times when the company goes public or is acquired. Lose, and everyone loses together \u2014 the company folds, shares become worthless, and the money investors put in is effectively thrown into the sea. The founder does not need to repay investors in cash. This is the essence of high-risk, high-return venture capital: shared risk."}),"\n",(0,i.jsx)(t.p,{children:"More importantly: in standard venture capital or angel investing, investors absolutely never require the founder to sign a Personal Guarantee (PG). Because startups typically operate as limited companies, meaning the company and the founder are legally separate entities. If the company goes bankrupt, liquidation covers the company's assets \u2014 it does not touch the founder's personal property, savings, or private assets. If an investor demanded that a founder sign PG \u2014 meaning business failure requires selling personal assets to repay \u2014 insiders would call this a \"poison pill clause,\" and no normal startup team would accept it."}),"\n",(0,i.jsx)(t.p,{children:'Of course, startup financing has exceptions. Convertible notes or SAFEs are common in very early-stage financing, but they are designed to automatically convert to equity in the next round and typically do not devolve into debt collection. Some investors (particularly traditional VCs in certain regions) include "ratchet clauses" or "buyback provisions," stipulating that if the company fails to IPO within a specified period, the founder must buy back shares. But in the mainstream tech startup world, excessively harsh personal buyback clauses are relatively rare.'}),"\n",(0,i.jsx)(t.p,{children:"And the situations in which a founder truly faces personal liability are usually limited to: fraud and falsified accounts (criminal offence), borrowing from banks in the company's name with a personal guarantee (banks play by entirely different rules from VCs), or signing predatory buyback clauses."}),"\n",(0,i.jsx)(t.p,{children:"Now place this control group back in the context of the Lofter case."}),"\n",(0,i.jsx)(t.p,{children:'Lofter\'s investors thought what they were doing was very close to "equity investment" \u2014 contributing money, buying shares, one share one vote, sharing profits if they win. But the moment they signed PG, the nature of the whole thing shifted from "equity investment" to "personally guaranteed lending." They adopted an "investment" mindset while assuming the legal liability of a "loan guarantor."'}),"\n",(0,i.jsx)(t.p,{children:"In standard startup financing, investors bear risk, but that risk has a ceiling \u2014 at most they lose their invested principal. In Lofter's model, PG-signing investors bore risk with no ceiling \u2014 Joint and Several Liability means they could be liable for the project company's entire debt, with interest continuing to accrue."}),"\n",(0,i.jsx)(t.p,{children:"In standard startup financing, any VC that asked a founder (the actual controller of the enterprise) to sign PG would have their clause labelled a poison pill. But Lofter didn't just ask the founder to sign \u2014 it asked retail investors with no control over the company's operations to sign too."}),"\n",(0,i.jsx)(t.p,{children:'This comparison reveals the most essential problem of Lofter\'s model: it used the language and packaging of "investment" to make investors believe they were participating in a risk-sharing commercial venture. But the existence of PG changed the legal nature of the entire thing from "investment" to "guarantee" \u2014 and most investors, at the time of signing, did not understand what this transformation meant.'}),"\n",(0,i.jsx)(t.h2,{id:"iv-the-second-type-lofters-information-asymmetry-toward-investors",children:"IV. The Second Type: Lofter's Information Asymmetry Toward Investors"}),"\n",(0,i.jsx)(t.p,{children:'The second type of "fraud" is entirely different in nature.'}),"\n",(0,i.jsx)(t.p,{children:'In an official clarification statement published by Lofter Group in 2021, the company explicitly stated: "Project stakeholders have the sole and absolute right to make day-to-day decisions and manage the project company. All day-to-day operational decisions are made by stakeholder vote in accordance with the Articles of Association." It further stated: "All funds are deposited directly into the project company\'s bank account and managed by the stakeholders themselves."'}),"\n",(0,i.jsx)(t.p,{children:"But the picture painted by victims and media reporting diverges markedly from this statement."}),"\n",(0,i.jsx)(t.p,{children:'Shareholders complained to the media about being treated as "ATM machines" and asked to inject additional capital proportionally. Shareholders in some projects questioned management efficiency; some even expressed intent to vote for the project company\'s liquidation \u2014 if shareholders truly had "sole and absolute decision-making and management rights," why was their liquidation intent not acted upon? Janice Chow herself did not appear on some project companies\' shareholder and director lists, yet the group she founded was effectively managing those projects \u2014 under this structure, what did "stakeholders manage themselves" actually mean in practice?'}),"\n",(0,i.jsx)(t.p,{children:"The more critical question is: were investors adequately informed of the following when they entered?"}),"\n",(0,i.jsx)(t.p,{children:"First, the project company's actual financial position \u2014 including real debt levels, detailed PE contract terms, and the rate of interest accumulation."}),"\n",(0,i.jsx)(t.p,{children:"Second, the possibility that they might later be asked to sign PG, and PG's actual legal consequences under Joint and Several Liability."}),"\n",(0,i.jsx)(t.p,{children:"Third, Lofter Group's actual role and power within the project \u2014 nominally a \"service provider,\" but in reality how much control did it have over the project's direction?"}),"\n",(0,i.jsx)(t.p,{children:'If investors made their investment decision and signed PG fully aware of all of the above, then this was indeed a "you bet, you lose" lawful gamble. But if the information they relied on to make their investment decision and sign PG was incomplete, embellished, or materially different from the actual situation \u2014 then this is no longer "lawful unfairness" but a potential legal issue involving misrepresentation or failure to disclose.'}),"\n",(0,i.jsx)(t.p,{children:'The dividing line between the two types of "fraud" lies precisely here.'}),"\n",(0,i.jsx)(t.h2,{id:"v-why-the-two-are-easily-confused",children:"V. Why the Two Are Easily Confused"}),"\n",(0,i.jsx)(t.p,{children:'The two types of "fraud" are easily conflated because their effects are highly similar \u2014 investors all feel "deceived," all suffer heavy losses, and all face the bottomless debt-collection pit of PG.'}),"\n",(0,i.jsx)(t.p,{children:"But the causes are entirely different."}),"\n",(0,i.jsx)(t.p,{children:"Damage caused by PE contracts stems from the inherently unfair design of the contractual terms. Even if investors had understood every single clause 100%, as long as the market turned, they would still face the same outcome. This damage is a product of contractual structure and is extremely difficult to pursue legally."}),"\n",(0,i.jsx)(t.p,{children:'But if the information investors relied on to make their decisions was flawed \u2014 told "13% returns" without being adequately informed of risks, guided into buying equity without knowing PG would later be required, told "one share, one vote" but actually having no control over the company\'s operations \u2014 this damage stems from information asymmetry and potentially touches upon company law, securities law, or even the common-law doctrines of misrepresentation or negligent misstatement.'}),"\n",(0,i.jsx)(t.p,{children:'A simple analogy: PE contracts are like a lawful gamble with massively tilted odds \u2014 you might lose terribly, but you knew what you were betting on. But if someone told you this was a "sure-win" investment, concealed the true odds of the gamble, or even pushed you onto the gambling table without your knowledge \u2014 that is not just "an unfair gamble" but "cheating."'}),"\n",(0,i.jsx)(t.p,{children:"The former is very hard to litigate. The latter has legal standing."}),"\n",(0,i.jsx)(t.h2,{id:"vi-the-grey-zone-of-mentor-referrals",children:"VI. The Grey Zone of Mentor Referrals"}),"\n",(0,i.jsx)(t.p,{children:"Within this framework, the role of investment mentors deserves even closer scrutiny."}),"\n",(0,i.jsx)(t.p,{children:"If mentors merely taught general property investment knowledge, collected course fees, and then students independently decided whether to invest in specific projects \u2014 this is normal commercial activity involving no violations."}),"\n",(0,i.jsx)(t.p,{children:"But if mentors directly promoted specific projects in their courses, cited specific return rates as selling points, channelled students toward specific investment vehicles, and themselves collected referral commissions or benefits \u2014 while students were not fully aware of the interest relationship between the mentor and the project party \u2014 then this enters a grey zone."}),"\n",(0,i.jsx)(t.p,{children:'Because in this scenario, students believed they were receiving "independent investment education," when in fact they were being steered toward a specific investment decision. The mentor\'s "independence" was superficial; their income structure naturally inclined them to promote investor entry.'}),"\n",(0,i.jsx)(t.p,{children:"This is entirely consistent with the \"fee structure determines freedom of speech\" analysis from the second article \u2014 the mentor's fee structure dictated that they could not genuinely stand in the student's interest to assess risk."}),"\n",(0,i.jsx)(t.p,{children:"But the deeper question is: does this kind of referral activity legally constitute \"investment advice\"? If it does, does the mentor need to hold the relevant licence? If it does not, how should legal liability be apportioned when a student's investment decision, made based on a mentor's referral, goes wrong?"}),"\n",(0,i.jsx)(t.p,{children:'These questions currently have no clear legal answers. But they are precisely the critical terrain that distinguishes "lawful unfairness" from "unlawful deception."'}),"\n",(0,i.jsx)(t.h2,{id:"vii-what-everyone-in-business-must-know",children:"VII. What Everyone in Business Must Know"}),"\n",(0,i.jsx)(t.p,{children:'The lessons of the Lofter case extend far beyond "property investment." Anyone running a business, co-founding a venture, or considering accepting financing should understand the following baseline principles.'}),"\n",(0,i.jsx)(t.p,{children:'First, distinguish "investment" from "lending." Someone puts money into your company\'s equity \u2014 win together, lose together \u2014 that is investment. Someone lends money to your company, and regardless of profit or loss you must repay principal plus interest \u2014 that is lending. The legal consequences are entirely different. If someone uses the language of "investment" to package what is substantively a "lending" transaction, you need to be especially careful.'}),"\n",(0,i.jsx)(t.p,{children:"Second, never sign a Personal Guarantee lightly. Once PG is signed, your personal assets are bound to the company's debt. The limited-company firewall \u2014 your greatest legal protection \u2014 is pierced. In the standard startup financing world, a VC requesting a founder to sign PG would be labelled a poison-pill clause. If anyone asks you to sign PG, you must first independently consult a lawyer, fully understand the complete consequences of Joint and Several Liability, and only then make your decision."}),"\n",(0,i.jsx)(t.p,{children:"Third, when co-investing in a business, the books must be transparent. If you partner with someone but they won't let you see the accounts, won't give you audit rights, and nominally call it \"one share, one vote\" but in reality you have no control over operations \u2014 this is not a partnership. This is lending your name and assets for someone else to use. You bear the responsibilities of a shareholder or even a guarantor, while enjoying only the rights of a bystander."}),"\n",(0,i.jsx)(t.p,{children:'Fourth, high returns necessarily entail high risk \u2014 but what you need to know is the specific shape of that risk. When someone tells you the return rate is 13%, the question to ask is not "is it possible," but "if it doesn\'t materialise, what specifically will I lose, how much, and for how long?" If the other party cannot or will not answer this question, you have just received the most important answer of all.'}),"\n",(0,i.jsx)(t.h2,{id:"viii-conclusion-same-affair-two-lines",children:"VIII. Conclusion: Same Affair, Two Lines"}),"\n",(0,i.jsx)(t.p,{children:"Returning to the original question: was the Lofter incident fraud or a gamble?"}),"\n",(0,i.jsx)(t.p,{children:"The answer is: within the same affair, two lines exist simultaneously."}),"\n",(0,i.jsx)(t.p,{children:"PE contract terms' suppression is lawful unfairness. Damage along this line stems from the contractual structure itself and is extremely difficult to pursue legally. Victims can condemn PE's predation on moral grounds but will have great difficulty winning in court."}),"\n",(0,i.jsx)(t.p,{children:"Whether Lofter (and possibly the referrers) met the legal standard for information disclosure to investors \u2014 that is the other line. If the information investors relied on to make their decisions contained material omissions or falsehoods, damage along this line stems from information asymmetry and has legal room for pursuit."}),"\n",(0,i.jsx)(t.p,{children:"The common ground of both lines is: investors lost. The distinction between them is: one is protected by the principle of contractual freedom; the other may cross the legal baseline of misrepresentation or investor protection."}),"\n",(0,i.jsx)(t.p,{children:'And the reason most public discourse has been confused is precisely the failure to separate these two lines. Conflating PE\'s lawful suppression with Lofter\'s information asymmetry leads to one of two outcomes: either everyone is labelled a "fraudster" \u2014 which doesn\'t hold up legally \u2014 or everyone is treated as a "lawful gambler" \u2014 which is far too lenient on potential regulatory violations.'}),"\n",(0,i.jsx)(t.p,{children:"The truth, as ever, lies somewhere between the two extremes."}),"\n",(0,i.jsx)(t.p,{children:"This article is not legal advice. Any investor who believes they were affected by misrepresentation or failure to disclose during the investment process should seek independent professional legal counsel to clarify whether their specific situation falls on one line or the other."})]})}function c(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(h,{...e})}):h(e)}},28453(e,t,n){n.d(t,{R:()=>a,x:()=>r});var i=n(96540);const s={},o=i.createContext(s);function a(e){const t=i.useContext(o);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),i.createElement(o.Provider,{value:t},e.children)}}}]);